#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){int n;scanf("%d",&n);vector<int>a(n);
int total=0;for(int i=0;i<n;++i){scanf("%d",&a[i]);total+=a[i];}
if(total%2){printf("NO\n");return 0;}
int half=total/2;
vector<bool>dp(half+1,false);dp[0]=true;
for(int x:a)for(int j=half;j>=x;--j)if(dp[j-x])dp[j]=true;
printf("%s\n",dp[half]?"YES":"NO");return 0;}

